<template><div><header class="page-head"><div><div class="eyebrow">基金详情 / {{code}}</div><h1>{{fund.fund_name}}</h1><p>实时估值 · 虚拟净值轨迹 · 贡献拆解</p></div><div class="score glass">估值可信度 <b>中</b><small>最近偏差 0.31%</small></div></header><section class="detail-grid"><div class="chart-card glass"><div class="metric"><span>实时估算</span><strong :class="estimate.est_change_pct>=0?'up':'down'">{{estimate.est_change_pct>=0?'+':''}}{{estimate.est_change_pct}}%</strong><small>估算净值 {{estimate.est_nav}}</small></div><div class="chart"><div v-for="(p,i) in timeline" :key="i" class="dot" :style="{left:(i/(Math.max(1,timeline.length-1))*96)+'%',bottom:(18+p.change_pct*55)+'%'}"></div><div class="line"></div><span class="axis a">09:30</span><span class="axis b">15:00</span></div></div><div class="glass contributors"><h3>今日贡献</h3><div v-for="x in estimate.top_contributors" :key="x.stock_code" class="contrib"><div><b>{{x.stock_name}}</b><small>权重 {{x.weight}}%</small></div><span>{{x.contribution>=0?'+':''}}{{x.contribution}}%</span></div></div></section></div></template><script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{getJSON}from'../api';const code=useRoute().params.code,fund=ref({}),estimate=ref({est_change_pct:0,est_nav:0,top_contributors:[]}),timeline=ref([]);onMounted(async()=>{const[a,b,c]=await Promise.all([getJSON('/funds/'+code),getJSON('/estimate/'+code),getJSON('/estimate/'+code+'/timeline')]);fund.value=a.data;estimate.value=b.data;timeline.value=c.data.points})</script>
